def check_interval(a, b):
    for i in range(1, 101):
        for j in range(1, 101):
            even_count = (j - i + 1) // 2 + ((j - i + 1) % 2 and (i % 2 == 0))
            odd_count = (j - i + 1) - even_count
            if even_count == a and odd_count == b:
                return "YES"
    return "NO"

# Read input
a, b = map(int, input().split())

# Output the result
print(check_interval(a, b))
